{
  "name": "Lambda 10-3 多滤光轮控制器",
  "name_en": "Lambda 10-3 multi-filter wheel controller",
  "manufacturer": "Sutter Instrument",
  "description": "用于显微成像等光学实验的微处理器控制多滤光轮系统，可驱动最多 3 个滤光轮并控制快门，实现滤光片的快速切换。",
  "description_en": "A microprocessor-controlled multi-filter wheel system for microscopy and other optical imaging setups, supporting up to three filter wheels and shutter control for rapid filter switching.",
  "tag_hints": [
    "motorized filter wheel",
    "microscopy imaging",
    "optical filter switching",
    "fluorescence microscopy",
    "shutter control",
    "multi-wheel filter system"
  ],
  "actions": [
    {
      "action_name": "auto-flush",
      "description": "刷新设备通信缓冲区。",
      "description_en": "Flush the device communication buffer."
    },
    {
      "action_name": "auto-motorsON_async",
      "description": "开启所有滤光轮电机电源。",
      "description_en": "Power on all filter wheel motors."
    },
    {
      "action_name": "auto-reset_async",
      "description": "复位控制器。",
      "description_en": "Reset the controller."
    },
    {
      "action_name": "auto-status_async",
      "description": "查询设备状态。",
      "description_en": "Query the device status."
    },
    {
      "action_name": "auto-open_A",
      "description": "打开 A 路快门。",
      "description_en": "Open shutter A."
    },
    {
      "action_name": "auto-position",
      "description": "设置滤光轮位置和切换速度；可控制 A/C 轮组或 B 轮。",
      "description_en": "Set the filter wheel position and switching speed; controls wheel group A/C or wheel B."
    },
    {
      "action_name": "auto-motorsON",
      "description": "开启所有滤光轮电机电源。",
      "description_en": "Power on all filter wheel motors."
    },
    {
      "action_name": "auto-status",
      "description": "查询设备状态。",
      "description_en": "Query the device status."
    },
    {
      "action_name": "auto-remote",
      "description": "设置本地/远程控制模式。",
      "description_en": "Set the local/remote control mode."
    },
    {
      "action_name": "auto-reset",
      "description": "复位控制器。",
      "description_en": "Reset the controller."
    }
  ]
}

